      --muted: #5A5A5F;
      --card: #FFFFFF;
      --card-border: transparent;
      --shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
      color-scheme: light;
    }

    [data-theme="dark"] {
      --bg: #14142B;
      --text: #F4F1DE;
      --muted: #B8B5A7;
      --card: #1F1F3D;
      --card-border: #34345A;
      --shadow: none;
      color-scheme: dark;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      font-size: 1rem;
      line-height: 1.6;
      transition: background-color 180ms ease, color 180ms ease;
    }

    a {
      color: var(--accent);
      text-decoration: underline;
      text-underline-offset: 0.25rem;
    }

    a:focus-visible,
    button:focus-visible {
      outline: 0.2rem solid var(--accent);
      outline-offset: 0.25rem;
    }

    .site-header {
      padding: 3rem 2rem;
      background: linear-gradient(120deg, var(--bg), rgba(228, 0, 124, 0.1));
    }

    .header-inner {
      max-width: 70rem;
      margin: 0 auto;
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 2rem;
    }

    .header-copy {
      min-width: 0;
    }

    h1 {
      margin: 0;
      font-size: 2.5rem;
      line-height: 1.15;
      letter-spacing: -0.04em;
    }

    .tagline {
      margin: 0.5rem 0 1rem;
      color: var(--muted);
      font-size: 1.125rem;
    }

    nav {
      display: flex;
      flex-wrap: wrap;
      gap: 1.5rem;
    }

    #theme-toggle {
      flex: 0 0 auto;
      min-width: 2.75rem;
      min-height: 2.75rem;
      padding: 0.5rem 1rem;
      border: 0.125rem solid var(--accent);
      border-radius: 999px;
      background: transparent;
      color: var(--accent);
      font: inherit;
      font-size: 1.25rem;
      line-height: 1;
      cursor: pointer;
      transition: background-color 150ms ease, color 150ms ease;
    }

    #theme-toggle:hover {
      background: var(--accent);
      color: #FFFFFF;
    }

    main {
      width: min(100% - 4rem, 70rem);
      margin: 0 auto;
    }

    section {
      padding: 3rem 0;
      scroll-margin-top: 1.5rem;
    }

    h2 {
      margin: 0 0 0.5rem;
      font-size: 1.75rem;
      line-height: 1.25;
      letter-spacing: -0.02em;
    }

    h3 {
      margin: 0;
      font-size: 1.25rem;
      line-height: 1.35;
    }

    .section-intro {
      max-width: 70ch;
      margin: 0 0 2rem;
      color: var(--muted);
    }

    .member-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
      gap: 1.5rem;
    }

    .member-card {
      min-width: 0;
      padding: 1.5rem;
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      background: var(--card);
      border: 1px solid var(--card-border);
      border-radius: 1rem;
      box-shadow: var(--shadow);
    }

    .member-card img {
      width: 8rem;
      height: 8rem;
      margin-bottom: 1rem;
      border-radius: 50%;
      object-fit: cover;
    }

    .study {
      margin: 0.5rem 0 1rem;
      color: var(--muted);
      font-size: 0.9rem;
    }

    .bio {
      max-width: 70ch;
      margin: 0 0 1rem;
    }

    .hot-take {
      margin: auto 0 0;
      padding: 0.5rem 1rem;
      background: var(--accent);
      border-radius: 0.5rem;
      color: #FFFFFF;
      font-size: 0.9rem;
      line-height: 1.5;
    }

    .future-panel {
      padding: 2rem;
      background: var(--card);
      border: 1px solid var(--card-border);
      border-radius: 1rem;
      box-shadow: var(--shadow);
    }

    .future-panel p {
      max-width: 70ch;
      margin: 0 0 1rem;
    }

    .future-panel h3 {
      margin: 1.5rem 0 0.5rem;
    }

    .future-panel ul {
      max-width: 70ch;
      margin: 0;
      padding-left: 1.5rem;
    }

    .prediction {
      color: var(--muted);
    }

    footer {
      padding: 2rem 1rem;
      color: var(--muted);
      text-align: center;
      font-size: 0.8rem;
    }

    @media (max-width: 700px) {
      .site-header {
        padding: 2rem 1rem;
      }

      .header-inner {
        flex-direction: column;
        align-items: flex-start;
        gap: 1.5rem;
      }

      main {
        width: calc(100% - 2rem);
      }

      .member-grid {
        grid-template-columns: 1fr;
      }

      .future-panel {
        padding: 1.5rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        transition-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="header-inner">
      <div class="header-copy">
        <h1>Patch &amp; Circumstance</h1>
        <p class="tagline">Five humans, one agent, and a frankly optimistic definition of “done.”</p>
        <nav aria-label="Main navigation">
          <a href="#team">Meet the team</a>
          <a href="#future-of-se">Our AI outlook</a>
        </nav>
      </div>
      <button id="theme-toggle" type="button" aria-label="Switch to night mode">☾</button>
    </div>
  </header>

  <main>
    <section id="team" aria-labelledby="team-heading">
      <h2 id="team-heading">Meet the team</h2>
      <p class="section-intro">
        We’re five computer science students at Paderborn University, learning how to build software with agents without outsourcing our ability to notice a suspicious semicolon. In the Agentic Software Engineering lab, security, curiosity, and a healthy respect for testing bring us together.
      </p>

      <div class="member-grid">
        <article class="member-card">
          <img src="{{image:Jenith_avatar.png}}" alt="Avatar of Jenith">
          <h3>Jenith</h3>
          <p class="study">M.Sc. Computer Science, Paderborn University</p>
          <p class="bio">
            Jenith studies computer science and is interested in cybersecurity, SOC operations, VAPT, Python, and network systems. AI assistants can speed up code, tests, and documentation, but they can miss system-wide context and slip in subtle security flaws. Jenith once debugged a network script for hours before discovering that one router rule had created the digital equivalent of a traffic jam.
          </p>
          <p class="hot-take">🔥 AI won't replace human minds; it can provide peace of mind—if humans know how to use it.</p>
        </article>

        <article class="member-card">
          <img src="{{image:prachi_avatar.png}}" alt="Avatar of Prachi">
          <h3>Prachi</h3>
          <p class="study">M.Sc. Computer Science, Paderborn University</p>
          <p class="bio">
            Prachi studies computer science and enjoys debugging, SOC operations, and travel. She sees AI as useful for small jobs such as simple code and tests, but notes that plausible-looking output can still be wrong. That makes careful human review especially important in security work. Prachi’s personal plot twist is that she is 23—not 15, despite what people apparently keep guessing.
          </p>
          <p class="hot-take">🔥 AI will not take your job. But someone who can check AI code well might.</p>
        </article>

        <article class="member-card">
          <img src="{{image:pratham_avatar.jpg}}" alt="Photo of Pratham">
          <h3>Pratham</h3>
          <p class="study">M.Sc. Computer Science, Paderborn University; B.Sc. Computer Science, University of Mumbai</p>
          <p class="bio">
            Pratham studies computer science and is into cybersecurity, AI, and anime. He finds AI useful for boilerplate and repetitive work, while keeping an eye on the security details it can gloss over. In his view, knowing networks and hardware still matters when checking whether generated software actually works. Away from the keyboard, Pratham builds custom DIY audio and home-theater systems—where “it works on my machine” has a very literal sound system.
          </p>
          <p class="hot-take">🔥 AI will write 90% of our code, and we will spend 100% of our time patching its security vulnerabilities.</p>
        </article>

        <article class="member-card">
          <img src="{{image:vaibhav_avatar.jpg}}" alt="Photo of Vaibhav">
          <h3>Vaibhav</h3>
          <p class="study">M.Sc. Computer Science, Paderborn University</p>
          <p class="bio">
            Vaibhav studies computer science and enjoys artificial intelligence, anime, and philosophy. He sees AI as a major change to software development, reducing the time spent writing code and fixing bugs. He is more optimistic than some of his teammates: he thinks future tools might turn an idea into working software with very little human intervention. He is also a huge Harry Potter movie fan, presumably prepared to inspect any suspiciously magical deployment.
          </p>
          <p class="hot-take">🔥 AI makes shipping software faster, but it trades deep critical thinking for security bugs.</p>
        </article>

        <article class="member-card">
          <img src="{{image:vatsal_avatar.jpeg}}" alt="Photo of Vatsal">
          <h3>Vatsal</h3>
          <p class="study">M.Sc. Computer Science, Paderborn University; B.E. Computer Engineering, CHARUSAT University</p>
          <p class="bio">
            Vatsal studies computer science and enjoys AI, anime, volleyball, sightseeing, and dramas. He thinks AI makes it easier and faster for developers to turn ideas into reality, and expects it to assist throughout the software-development process. He’s reserved at first but open with friends—which is a useful reminder that good collaboration, like good software, takes more than a flashy first impression.
          </p>
          <p class="hot-take">🔥 AI can handle routine tasks with ease; the real challenge is making its systems secure, reliable, and trusted.</p>
        </article>
      </div>
    </section>

    <section id="future-of-se" aria-labelledby="future-heading">
      <h2 id="future-heading">The Future of Software Engineering</h2>
      <div class="future-panel">
        <p>
          Our shared outlook: AI is already a capable assistant, not an infallible teammate. It can draft routine code, tests, and first passes quickly; it can also be confidently wrong, overlook system context, or leave security holes. The more code agents produce, the more valuable careful human judgment becomes.
        </p>

        <h3>Things we agree on</h3>
        <ul>
          <li>Generated code needs human review, testing, and security checks before it earns a place in production.</li>
          <li>People will spend less time typing routine code and more time shaping systems, validating behavior, and handling edge cases.</li>
          <li>Strong fundamentals still matter: you need to understand a system to spot when an agent has misunderstood it.</li>
          <li>AI is most helpful when people use it with clear intent and sensible guardrails—not blind faith and a big “deploy” button.</li>
        </ul>

        <h3>Where our crystal ball disagrees</h3>
        <p>
          Vaibhav can imagine AI automating almost the whole process, from an idea to finished software. Prachi, Jenith, Pratham, and Vatsal expect people to stay closely involved as architects, reviewers, and security-minded problem solvers. We agree on one detail either way: somebody will still have to decide whether “looks plausible” means “ship it.”
        </p>

        <h3>Predictions, cautiously deployed</h3>
        <ul class="prediction">
          <li><strong>2030:</strong> “Generate the boilerplate” becomes a normal request—and “show me the tests” becomes the immediate follow-up.</li>
          <li><strong>2035:</strong> Code review is less about counting lines and more about asking whether the agent understood the assignment.</li>
        </ul>
      </div>
    </section>
  </main>

  <footer>
    Built by an agent, supervised by humans. <span id="year"></span> · Patch &amp; Circumstance
  </footer>

  <script>
    const themeToggle = document.getElementById("theme-toggle");

    function updateThemeButton(theme) {
      const nightMode = theme === "dark";
      themeToggle.textContent = nightMode ? "☀" : "☾";
      themeToggle.setAttribute(
        "aria-label",
        nightMode ? "Switch to day mode" : "Switch to night mode"
      );
    }

    updateThemeButton(document.documentElement.getAttribute("data-theme"));

    themeToggle.addEventListener("click", () => {
      const currentTheme = document.documentElement.getAttribute("data-theme");
      const nextTheme = currentTheme === "dark" ? "light" : "dark";
      document.documentElement.setAttribute("data-theme", nextTheme);
      try {
        localStorage.setItem("upb-theme", nextTheme);
      } catch (error) {}
      updateThemeButton(nextTheme);
    });

    document.getElementById("year").textContent = new Date().getFullYear();
  </script>
</body>
</html>
